def summarize(values):
    total, bad = 0, 0
    for value in values:
        try:
            number = int(value)
            if number < 0 or isinstance(value, bool):
                bad += 1
                continue
            total += number
        except (ValueError, TypeError):
            bad += 1
    return total, bad

print(summarize(["10", "oops", "20", None, "30"]))

from fastapi import FastAPI
from pydantic import BaseModel, Field

app = FastAPI()

class Invoice(BaseModel):
    amount: float = Field(ge=0)
    days_overdue: int = Field(ge=0)

@app.get("/health")
def health():
    return {"status": "ok"}

@app.post("/score")
def score(invoice: Invoice):
    return {"risk_flag": invoice.days_overdue >= 30, "kind": "rule_only"}
